import {METRICS} from './core.js';
import {summarizeBaseline,comparePersonal,BASELINE_VERSION} from './personal-baselines.js';
import {evaluateMeasurement,detectHealthTrends} from './health-evaluation.js';
import {referenceLibrary} from './research-library.js';
import {buildChartModel,renderHealthChart,dateKey} from './health-charts.js';
import {DEMO_STORAGE_KEY,createDemoCrew,validateDemoCrew,readDemoCrew,saveDemoCrew,addDemoObservation,clearDemoCrew} from './demo-crew.js';

export const DUAL_STORAGE_KEY='cosmovital-dual-baseline-v1';
const clone=value=>structuredClone(value);
const plain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const fresh=()=>({schemaVersion:1,acknowledgements:{real:{},demo:{}},history:{real:[],demo:[]}});
const validTime=value=>typeof value==='string'&&Number.isFinite(Date.parse(value));
export function validateDualState(raw){
 if(!plain(raw)||raw.schemaVersion!==1||!plain(raw.acknowledgements)||!plain(raw.history))throw new Error('Invalid baseline audit state.');
 const result=fresh();
 for(const mode of ['real','demo']){
  if(!plain(raw.acknowledgements[mode])||Object.keys(raw.acknowledgements[mode]).length>1000||!Array.isArray(raw.history[mode])||raw.history[mode].length>500)throw new Error('Invalid baseline audit history.');
  for(const [id,at]of Object.entries(raw.acknowledgements[mode])){if(!/^trend-[a-zA-Z0-9_-]{1,120}$/.test(id)||!validTime(at))throw new Error('Invalid trend acknowledgement.');result.acknowledgements[mode][id]=at}
  for(const snapshot of raw.history[mode]){
   if(!plain(snapshot)||snapshot.simulated!==(mode==='demo')||snapshot.version!==BASELINE_VERSION||!METRICS[snapshot.metric]||!validTime(snapshot.computedAt)||!validTime(snapshot.asOf)||typeof snapshot.fingerprint!=='string'||snapshot.fingerprint.length>250000||!['preflight','early-mission','rolling'].includes(snapshot.type)||typeof snapshot.context!=='string'||!Array.isArray(snapshot.recordIds)||snapshot.recordIds.length>10000||snapshot.recordIds.some(id=>typeof id!=='string'||id.length>100)||!Number.isFinite(snapshot.median)||snapshot.mad!==null&&!Number.isFinite(snapshot.mad)||!plain(snapshot.range)||!Number.isFinite(snapshot.range.low)||!Number.isFinite(snapshot.range.high)||snapshot.range.low>snapshot.range.high)throw new Error('Invalid baseline audit snapshot.');
   result.history[mode].push(clone(snapshot));
  }
 }
 return result;
}

export function createDualBaselineUI(ctx){
 const {t,esc,icon,getRecords,getSettings,render,download}=ctx;
 const locale=()=>t('en-GB','ar-EG');
 const words=value=>Array.isArray(value)?t(value[0],value[1]):value&&typeof value==='object'?t(value.en||'',value.ar||value.en||''):String(value||'');
 const stamp=value=>{try{return new Date(value).toLocaleString(locale(),{timeZone:getSettings().timeZone||'UTC'})}catch{return String(value||'—')}};
 const number=value=>Number.isFinite(value)?value.toLocaleString(locale(),{maximumFractionDigits:2}):'—';
 const label=metric=>t(METRICS[metric]?.label||metric,METRICS[metric]?.ar||metric);
 const periodNames={'24h':['24 hours','٢٤ ساعة'],'7d':['7 days','٧ أيام'],'14d':['14 days','١٤ يومًا'],'30d':['30 days','٣٠ يومًا']};
 const typeNames={preflight:['Preflight baseline','خط الأساس قبل الرحلة'],'early-mission':['Early mission baseline','خط أساس بداية المهمة'],rolling:['Rolling in-flight baseline','خط الأساس المتحرك أثناء الرحلة']};
 const contextNames={resting:['Resting','في الراحة'],exercise:['During exercise','أثناء التمرين'],'post-exercise':['Post-exercise','بعد التمرين'],'post-eva':['Post-EVA','بعد السير الفضائي'],sleep:['Sleep','أثناء النوم'],other:['Other','أخرى'],unknown:['Unknown','غير معروف']};
 const categoryNames={stable:['Stable','مستقر'],improving:['Improving','اتجاه تحسن وصفي'],'needs-attention':['Needs Attention','يحتاج انتباهًا'],'review-recommended':['Review Recommended','المراجعة موصى بها'],insufficient:['Insufficient Data','بيانات غير كافية']};
 let demo=null,dual=fresh(),error='',feedback='',selectedMetric='heart',selectedPeriod='7d',selectedChartRange='7',selectedContext=getSettings().baselineContext||'resting',demoType='early-mission',demoRolling=14,followUpId='',researchConfirmed=false,recoveryRequired=false;
 function storage(){try{return globalThis.localStorage}catch{return null}}
 function reload(){error='';recoveryRequired=false;try{demo=readDemoCrew(storage());const raw=storage()?.getItem(DUAL_STORAGE_KEY);dual=raw===null||raw===undefined?fresh():validateDualState(JSON.parse(raw))}catch(issue){recoveryRequired=true;error=t('Saved baseline/demo data needs recovery: ','بيانات الأساس أو المحاكاة تحتاج استرجاعًا: ')+issue.message;demo=null;dual=fresh()}}
 reload();
 const mode=()=>demo?.active?'demo':'real';
 const simulatedRecord=record=>[record?.simulated,record?.training,record?.synthetic].some(value=>value===true||typeof value==='string'&&['true','yes','1'].includes(value.trim().toLowerCase()))||/(?:simulat|synthetic|demo|training)/i.test([record?.source,record?.source_tag,record?.mode].join(' '));
 const researchRecord=record=>record?.research===true||record?.spaceWeather===true||/(?:research|space.?weather|published.?summary|nasa|osdr)/i.test([record?.source,record?.source_tag,record?.source_type,record?.mode,record?.data_category,record?.classification].filter(Boolean).join(' '));
 const modeRecords=forDemo=>(forDemo?demo?.records||[]:getRecords()).filter(record=>record&&typeof record==='object'&&!researchRecord(record)&&(forDemo?record.simulated===true:!simulatedRecord(record)));
 const records=()=>modeRecords(mode()==='demo');
 const missionStart=forDemo=>forDemo?demo?.mission.start:getSettings().missionStart||(getSettings().start?getSettings().start+'T00:00:00Z':null);
 function options(forDemo=mode()==='demo'){const settings=getSettings();return {baselineType:forDemo?demoType:settings.baselineType||'preflight',type:forDemo?demoType:settings.baselineType||'preflight',context:selectedContext,missionStart:missionStart(forDemo),earlyMissionDays:Number(settings.earlyMissionDays)||7,rollingDays:forDemo?demoRolling:Number(settings.rollingDays)||14,demo:forDemo,contextConfirmed:researchConfirmed}}
 function writeDual(next){if(recoveryRequired)throw new Error(t('Recover a valid backup before replacing unreadable analysis data.','استرجع نسخة سليمة قبل استبدال بيانات التحليل غير المقروءة.'));const checked=validateDualState(next),local=storage();if(!local)throw new Error(t('Local storage is unavailable; export your report.','التخزين المحلي غير متاح؛ صدّر تقريرك.'));local.setItem(DUAL_STORAGE_KEY,JSON.stringify(checked));dual=checked}
 function persistDemo(next){if(recoveryRequired)throw new Error(t('Recover a valid backup before replacing unreadable analysis data.','استرجع نسخة سليمة قبل استبدال بيانات التحليل غير المقروءة.'));demo=saveDemoCrew(next,storage())}
 function isDemoActive(){return mode()==='demo'}
 function getDemoRecords(){return isDemoActive()?clone(modeRecords(true)):[]}
 function demoMission(){return isDemoActive()?clone(demo.mission):null}
 function analysisTime(forDemo){const times=forDemo?modeRecords(true).map(record=>Date.parse(record.timestamp)).filter(Number.isFinite):[];return times.length?Math.max(...times):Date.now()}
 function getJudgeDemoSummary(){
  if(!isDemoActive())return null;
  const input=modeRecords(true),timeZone=getSettings().timeZone||'UTC',asOf=new Date(analysisTime(true)).toISOString();
  const window=buildChartModel(input,'heart',{range:'7',timeZone,now:asOf,dataMode:'demo'});
  const recent=input.filter(record=>{const time=Date.parse(record.timestamp);return time>=window.start&&time<=window.end});
  const metricCounts=Object.fromEntries(Object.keys(METRICS).map(metric=>[metric,recent.filter(record=>Number.isFinite(record.values?.[metric])).length]));
  const times=recent.map(record=>Date.parse(record.timestamp)).sort((a,b)=>a-b);
  return {simulated:true,range:'7',asOf,start:new Date(window.start).toISOString(),end:new Date(window.end).toISOString(),timeZone,recordCount:recent.length,measurementCount:recent.reduce((count,record)=>count+Object.values(record.values).filter(Number.isFinite).length,0),observedDays:new Set(recent.map(record=>dateKey(record.timestamp,timeZone))).size,metricCounts,firstRecordedAt:times.length?new Date(times[0]).toISOString():null,lastRecordedAt:times.length?new Date(times.at(-1)).toISOString():null,totalStoredRecords:input.length};
 }
 function startJudgeDemo(){
  persistDemo(demo?{...clone(demo),active:true}:createDemoCrew());
  selectedChartRange='7';selectedPeriod='7d';selectedMetric='heart';selectedContext='resting';demoType='early-mission';researchConfirmed=false;followUpId='';error='';
  feedback=t('Your simulated seven-day preview is ready. Earlier scenario records remain available for baseline calibration.','معاينة الأسبوع المحاكى جاهزة. سجلات السيناريو الأقدم تظل متاحة لبناء الخط المرجعي.');
  return getJudgeDemoSummary();
 }

 function retainBaseline(baseline,at,forDemo){
  if(baseline?.status!=='established'||!baseline.range)return;
  const fingerprint=JSON.stringify([baseline.version,baseline.metric,baseline.type,baseline.context,baseline.windowStart,baseline.windowEnd,baseline.recordIds,baseline.median,baseline.mad,baseline.range]);
  const key=forDemo?'demo':'real';if(dual.history[key].some(item=>item.fingerprint===fingerprint))return;
  const snapshot={version:baseline.version,computedAt:new Date().toISOString(),asOf:at,metric:baseline.metric,type:baseline.type,context:baseline.context,missionStart:missionStart(forDemo),recordIds:[...baseline.recordIds],fingerprint,median:baseline.median,mad:baseline.mad,range:clone(baseline.range),count:baseline.count,days:baseline.days,simulated:forDemo};
  const next=clone(dual);next.history[key].push(snapshot);next.history[key]=next.history[key].slice(-500);
  try{writeDual(next)}catch(issue){error=t('Baseline snapshot was not saved: ','لم تُحفظ لقطة خط الأساس: ')+issue.message}
 }
 function latest(input,metric,context){return [...input].filter(record=>Number.isFinite(record.values?.[metric])&&record.context===context).sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp)).at(-1)||null}
 function metricModel(metric,forDemo=mode()==='demo'){
  const input=modeRecords(forDemo),opts={...options(forDemo),context:metric==='sleep'&&selectedContext==='resting'?'sleep':selectedContext};
  const current=latest(input,metric,opts.context),at=current?.timestamp||new Date().toISOString();
  const evaluation=current?evaluateMeasurement(current,input,{...opts,metric}):null;
  const baseline=evaluation?.metrics?.[metric]?.layers?.personal?.baseline||summarizeBaseline(input,{...opts,metric,type:opts.baselineType,asOf:at,currentRecordId:current?.id});
  retainBaseline(baseline,at,forDemo);
  const comparison=evaluation?.metrics?.[metric]?.layers?.personal?.comparison||comparePersonal(current?.values?.[metric],baseline);
  const historicalBaseline=baseline.status==='established'?baseline:summarizeBaseline(input,{...opts,metric,type:opts.baselineType,asOf:at,currentRecordId:current?.id});
  if(historicalBaseline!==baseline)retainBaseline(historicalBaseline,at,forDemo);
  const research=evaluation?.metrics?.[metric]?.layers?.research||evaluation?.layers?.research||null;
  const safety=evaluation?.layers?.safety||evaluation?.metrics?.[metric]?.layers?.safety||null;
  return {metric,current,baseline,historicalBaseline,comparison,research,safety,evaluation,context:opts.context,simulated:forDemo};
 }
 function allTrends(forDemo=mode()==='demo'){
  const input=modeRecords(forDemo),now=new Date(analysisTime(forDemo)).toISOString(),base=options(forDemo);
  return detectHealthTrends(input,{...base,context:undefined,period:selectedPeriod,asOf:now});
 }
 const isReview=trend=>['needs-attention','review-recommended'].includes(trend.category||trend.classification);
 function baselineReason(reason){
  const explanations={
   'insufficient-observations':['At least five eligible observations across three different UTC dates are needed. The current reading is not used to establish its own baseline.','يلزم خمسة قياسات مؤهلة على الأقل في ثلاثة تواريخ UTC مختلفة. القراءة الحالية لا تدخل في بناء المرجع الذي تُقارن به.'],
   'mission-start-required':['Set the mission start date in workspace settings so preflight and in-flight observations can be separated.','حدد بداية المهمة في إعدادات مساحة العمل لفصل قياسات ما قبل الرحلة عن قياسات الرحلة.'],
   'invalid-configuration':['The indicator, baseline period or analysis timestamp is invalid. Review the selected analysis settings.','المؤشر أو فترة خط الأساس أو وقت التحليل غير صالح. راجع إعدادات التحليل المختارة.'],
   'invalid-window-configuration':['Choose a rolling window from 7 to 14 days and a valid early-mission window.','اختار نافذة متحركة من ٧ إلى ١٤ يومًا وفترة بداية مهمة صالحة.'],
   'measurement-context-required':['Choose a known activity context. Unknown or unspecified activity cannot establish a comparable baseline.','اختار ظروف نشاط معلومة. النشاط المجهول أو غير المحدد لا يثبت مرجعًا قابلًا للمقارنة.'],
   'early-mission-window-incomplete':['The selected early-mission adaptation window has not finished at the time of this reading. It cannot yet serve as a completed historical baseline.','فترة التكيف المختارة في بداية المهمة لم تكتمل عند وقت هذه القراءة؛ لا يمكن استخدامها كمرجع تاريخي مكتمل بعد.'],
   'baseline-period-not-started':['The selected baseline period had not started at the measurement time. Choose an appropriate period.','الفترة المرجعية المختارة لم تبدأ عند وقت القياس. اختار فترة مناسبة.'],
   'mixed-acquisition-context':['The eligible history contains different devices, methods or metric-specific conditions. Keep comparable acquisition conditions before establishing one baseline.','التاريخ المؤهل يحتوي أجهزة أو طرقًا أو ظروف قياس مختلفة. حافظ على ظروف جمع قابلة للمقارنة قبل بناء خط أساس واحد.']
  };
  return explanations[reason]?t(...explanations[reason]):t('The available history does not yet establish a compatible personal baseline. Review the observation counts and excluded conditions below.','التاريخ المتاح لا يثبت خط أساس شخصيًا متوافقًا بعد. راجع عدد القياسات والظروف المستبعدة أدناه.');
 }
 function baselineSelection(base){
  const reasons={
   'nonpersonal-research-data':['Research or space-weather record, not personal history','تسجيل بحثي أو طقس فضائي، وليس تاريخًا شخصيًا'],'invalid-record':['Invalid record','تسجيل غير صالح'],'conflicting-identifier':['Conflicting record ID','معرّف تسجيل متعارض'],'duplicate-identifier':['Duplicate record ID','معرّف تسجيل مكرر'],
   'different-data-mode':['Other real/simulated workspace','مساحة بيانات حقيقية أو محاكاة أخرى'],'invalid-measurements':['Invalid measurement values','قيم قياس غير صالحة'],'metric-not-recorded':['Indicator not collected','المؤشر لم يُجمع'],
   'invalid-timestamp':['Invalid measurement time','وقت قياس غير صالح'],'current-or-future-measurement':['Current or later measurement','قراءة حالية أو لاحقة'],'outside-baseline-period':['Outside selected baseline period','خارج الفترة المرجعية المختارة'],
   'different-activity-context':['Different activity context','ظروف نشاط مختلفة'],'unstable-signal':['Reported unstable signal','إشارة غير مستقرة مُبلغ عنها'],'different-acquisition-context':['Different acquisition conditions','ظروف جمع مختلفة'],
   'missing-acquisition-context':['Missing device, method or required context','غياب الجهاز أو الطريقة أو سياق مطلوب'],'duplicate-observation':['Repeated copy of an observation','نسخة مكررة من قياس'],'urgent-safety-prompt':['Independent urgent safety prompt','تنبيه سلامة عاجل مستقل']
  };
  const excluded=Object.entries(base.excludedReasons||{}).filter(([,count])=>count>0);
  return `<details class="dual-baseline-selection"><summary>${t('Why these observations were selected','لماذا اختيرت هذه القياسات؟')}</summary><p>${base.count||0} / ${base.minimumObservations||5} ${t('eligible observations required','قياسات مؤهلة مطلوبة')} · ${base.days||0} / ${base.minimumUtcDays||3} ${t('distinct UTC dates required','تواريخ UTC مختلفة مطلوبة')}</p>${base.mixedFields?.length?`<p>${t('Inconsistent fields','حقول غير متسقة')}: ${esc(base.mixedFields.join(' · '))}</p>`:''}${excluded.length?`<ul>${excluded.map(([reason,count])=>`<li>${esc(reasons[reason]?t(...reasons[reason]):t('Excluded observation','قياس مستبعد'))}: ${count}</li>`).join('')}</ul>`:`<p>${t('No additional exclusion was recorded. The selected time window and minimum sample size still apply.','لم يُسجل استبعاد إضافي. يظل شرط الفترة المختارة والحد الأدنى للعينات قائمًا.')}</p>`}</details>`;
 }
 function historicalReference(model){
  const historical=model.historicalBaseline;
  if(model.baseline.status==='established'||historical?.status!=='established')return '';
  const names={device:['Device','الجهاز'],method:['Method','الطريقة'],posture:['Posture','الوضعية'],temperatureSite:['Temperature site','موضع الحرارة'],glucoseTiming:['Glucose meal context','توقيت السكر مع الأكل'],hrvMethod:['HRV method','طريقة HRV']};
  const context=historical.contextFingerprint||{};
  const changed=Object.keys(names).filter(key=>String(context[key]||'unknown').trim().toLowerCase()!==String(model.current?.meta?.[key]||'unknown').trim().toLowerCase());
  return `<aside class="dual-historical-reference"><h3>${t('Historical baseline exists; current comparison is unavailable','يوجد خط أساس تاريخي؛ المقارنة الحالية غير متاحة')}</h3><p>${t(...typeNames[historical.type])} · ${t('Personal median','الوسيط الشخصي')}: <strong dir="ltr">${number(historical.median)} ${esc(METRICS[model.metric].unit)}</strong> · ${t('Descriptive historical interval','المجال التاريخي الوصفي')}: <span dir="ltr">${number(historical.range.low)}–${number(historical.range.high)}</span></p><p>${historical.count} ${t('historical observations','قياسات تاريخية')} · ${historical.days} ${t('UTC dates','تواريخ UTC')}${changed.length?' · '+t('Changed or missing conditions: ','ظروف مختلفة أو ناقصة: ')+changed.map(key=>t(...names[key])).map(esc).join(' · '):''}</p><p>${t('This history is retained, but its acquisition conditions do not establish comparability with the current reading. It is not overlaid onto incompatible chart observations and does not cancel medical warnings.','هذا التاريخ محفوظ، لكن ظروف جمعه لا تثبت قابلية المقارنة بالقراءة الحالية. لا يُرسم فوق قياسات غير متوافقة ولا يلغي التحذيرات الطبية.')}</p></aside>`;
 }
 function buildHistoryModel(model){
  const input=modeRecords(model.simulated),metric=['sys','dia'].includes(model.metric)?'bp':model.metric;
  const same=record=>{
   if(record.context!==model.context)return false;
   if(!model.current)return true;
   const fields=['device','method','posture',...(model.metric==='temp'?['temperatureSite']:model.metric==='glucose'?['glucoseTiming']:model.metric==='hrv'?['hrvMethod']:[])];
   return fields.every(key=>String(record.meta?.[key]||'unknown').trim().toLowerCase()===String(model.current.meta?.[key]||'unknown').trim().toLowerCase());
  };
  const comparable=input.filter(same),settings=getSettings();
  const personalBaseline=metric==='bp'?{sys:metricModel('sys',model.simulated).baseline,dia:metricModel('dia',model.simulated).baseline}:['mood','energy'].includes(metric)?undefined:model.baseline;
  return buildChartModel(comparable,metric,{range:selectedChartRange,timeZone:settings.timeZone||'UTC',now:analysisTime(model.simulated),unitPreferences:settings,dataMode:model.simulated?'demo':'personal',personalBaseline});
 }
 function chartView(model){
  const chartModel=buildHistoryModel(model);
  const chart=renderHealthChart(chartModel,{lang:t('en','ar'),locale:locale(),compact:(globalThis.innerWidth||1024)<700});
  const chartKeys=chartModel.metric==='bp'?['sys','dia']:[model.metric],allWindow=modeRecords(model.simulated).filter(record=>Date.parse(record.timestamp)>=chartModel.start&&Date.parse(record.timestamp)<=chartModel.end&&chartKeys.some(key=>Number.isFinite(record.values?.[key]))),shownIds=new Set(chartModel.points.map(point=>point.recordId)),omitted=allWindow.filter(record=>!shownIds.has(record.id)).length;
  return `<section class="panel panel-pad dual-history-chart" data-dual-chart-mode="${model.simulated?'demo':'personal'}"><div class="section-heading"><div><span class="eyebrow">${model.simulated?t('SIMULATED OBSERVATIONS ONLY','قياسات المحاكاة فقط'):t('PERSONAL OBSERVATIONS ONLY','القياسات الشخصية فقط')}</span><h2>${t('Your recorded history and personal baseline','تاريخ قياساتك وخط الأساس الشخصي')}</h2></div><div class="segmented dual-chart-ranges" aria-label="${t('Chart time range','الفترة الزمنية للرسم')}">${[['24','24 Hours','٢٤ ساعة'],['7','7 Days','٧ أيام'],['30','30 Days','٣٠ يومًا']].map(([range,en,ar])=>`<button type="button" data-action="dual-chart-range" data-range="${range}" class="${selectedChartRange===range?'active':''}" aria-pressed="${selectedChartRange===range}">${t(en,ar)}</button>`).join('')}</div></div><p class="dual-chart-context">${esc(label(model.metric))} · ${t(...(contextNames[model.context]||contextNames.unknown))} · ${t('same recorded acquisition conditions as the current observation','بنفس ظروف جمع القراءة الحالية المسجلة')}${model.current?.meta?.device?' · '+esc(model.current.meta.device):''}${model.current?.meta?.method?' · '+esc(model.current.meta.method):''}</p>${omitted?`<p class="dual-chart-explanation">${omitted} ${t('observations with other recorded conditions are omitted from this chart. Their original records remain in the workspace.','تسجيلات بظروف مسجلة مختلفة لا تظهر في هذا الرسم. تظل سجلاتها الأصلية محفوظة في مساحة العمل.')}</p>`:''}<p class="dual-chart-explanation">${t('The chart shows actual observations. A personal median or shaded interval describes eligible historical records; it is not a safety limit. NASA mean ± SD stays in the separate published-research panel, never a chart safety band.','الرسم يعرض قياسات فعلية. الوسيط الشخصي أو المجال المظلل يصف السجل التاريخي المؤهل؛ ليس حد أمان. متوسط ناسا ± الانحراف المعياري يبقى في قسم البحث المنشور المنفصل، وليس مجال أمان بالرسم.')}</p>${model.simulated?`<p class="dual-chart-explanation">${t('Simulated scenario snapshot','لقطة السيناريو المحاكى')}: <time datetime="${esc(new Date(analysisTime(true)).toISOString())}">${esc(stamp(analysisTime(true)))}</time>. ${t('The window ends at the latest saved scenario observation; dates are not shifted to today.','تنتهي النافذة عند أحدث قياس محفوظ بالسيناريو؛ لا تتغير التواريخ لتصبح اليوم.')}</p>`:''}${chart}<p class="dual-chart-explanation">${t('These chart controls only change the displayed history. The longitudinal review period remains separately selected above.','أزرار الرسم تغيّر التاريخ المعروض فقط. فترة مراجعة الاتجاه الطولي تُختار بشكل منفصل بالأعلى.')}</p></section>`;
 }
 function safetyText(safety){const status=safety?.status;if(status==='review-required')return t('Medical Safety Review Required','مطلوب مراجعة السلامة الطبية');if(status==='reference-review')return t('General medical reference review','مراجعة وفق المرجع الطبي العام');return t('No matching automatic prompt — this does not establish safety.','لا يوجد تنبيه تلقائي مطابق؛ ده لا يثبت السلامة.')}
 function researchText(research){if(!research||research.status==='unavailable')return t('NASA Spaceflight Reference: Insufficient Published Data','مرجع ناسا الفضائي: البيانات المنشورة غير كافية');return research.status==='summary-only'?t('Compatible descriptive summary; no participant-level distribution available.','ملخص وصفي متوافق؛ لا يتوفر توزيع لقياسات الأفراد.'):t('NASA Spaceflight Research Reference Distribution','توزيع مرجعي بحثي لرحلات ناسا الفضائية')}
 function researchDetails(research){const summary=research?.summary||research?.availableGroupSummary;return `<p>${esc(researchText(research))}</p>${summary?`<p><span dir="ltr">${number(summary.mean)} ± ${number(summary.standardDeviation)} ${esc(summary.unit||'')}</span> · ${t('published group mean ± SD','متوسط المجموعة المنشور ± الانحراف المعياري')}</p>`:''}${research?.reason?`<p class="dual-muted">${esc(words(research.reason))}</p>`:''}${research?.sourceUrl?`<a class="text-link" href="${esc(research.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('Original research source','مصدر البحث الأصلي')}${icon('external')}</a>`:''}<a class="text-link" href="#space-references">${t('Inspect source and sampling context','راجع المصدر وسياق أخذ العينات')}${icon('external')}</a>`}
 function resultLabel(code){const labels={'medical-safety-review-required':['Medical Safety Review Required','مراجعة السلامة الطبية مطلوبة'],'medical-reference-review-recommended':['Medical Reference Review Recommended','مراجعة المرجع الطبي موصى بها'],'personal-trend-review-recommended':['Personal Trend Review Recommended','مراجعة التغير الشخصي موصى بها'],'research-reference-difference-review-context':['Research Reference Difference — Review Context','اختلاف عن المرجع البحثي — راجع السياق'],'dual-baseline-monitoring-active':['Dual-Baseline Monitoring Active','المتابعة بخطين مرجعيين مفعلة'],'personal-baseline-monitoring-active':['Personal Baseline Monitoring Active','المتابعة بالمرجع الشخصي مفعلة']};return labels[code]?t(...labels[code]):t('Insufficient Personal Data','بيانات شخصية غير كافية')}
 function threeLayers(model){return `<div class="dual-evaluation-result" role="status"><strong>${esc(resultLabel(model.evaluation?.resultCode))}</strong></div><div class="dual-layers"><article><span class="eyebrow">A · ${t('GENERAL MEDICAL SAFETY','السلامة الطبية العامة')}</span><h3>${esc(safetyText(model.safety))}</h3><p>${t('Independent broad adult medical references. Personal or research similarity never cancels these prompts. Symptoms take priority.','مراجع طبية عامة للبالغين مستقلة عن المقارنات. التشابه مع تاريخك أو البحث لا يلغيها. الأعراض لها الأولوية.')}</p>${(model.safety?.prompts||[]).map(prompt=>`<p>${esc(words(prompt.title))}: ${esc(words(prompt.detail||prompt.message))}</p>`).join('')}</article><article><span class="eyebrow">B · ${t('SPACEFLIGHT RESEARCH','أبحاث الرحلات الفضائية')}</span><h3>${t('Context before comparison','السياق قبل المقارنة')}</h3>${researchDetails(model.research)}</article><article><span class="eyebrow">C · ${t('PERSONAL HISTORY','التاريخ الشخصي')}</span><h3>${model.comparison?.unusual?t('Personal Trend Review Recommended','مراجعة التغير الشخصي موصى بها'):model.baseline.status==='established'?t('Personal Baseline Monitoring Active','المتابعة بخط الأساس الشخصي مفعلة'):t('Insufficient Personal Data','بيانات شخصية غير كافية')}</h3><p>${model.comparison?.available?t('Absolute deviation: ','مقدار الانحراف المطلق: ')+number(model.comparison.absoluteDeviation)+' '+METRICS[model.metric].unit:t('A compatible, sufficiently sampled baseline is required.','المقارنة تحتاج خط أساس متوافقًا بعدد قياسات وأيام كافٍ.')}</p><p>${t('No weighted score, diagnosis or medical clearance is produced.','لا تُنتج درجة موزونة أو تشخيصًا أو تصريحًا بالسلامة.')}</p></article></div>`}
 function baselineCard(model){const base=model.baseline;return `<section class="panel panel-pad"><div class="section-heading"><h2>${esc(label(model.metric))}</h2><span class="pill">${model.simulated?t('SIMULATED CREW','طاقم محاكى'):t('PERSONAL RECORDS','تسجيلات شخصية')}</span></div><dl class="dual-stats"><div><dt>${t('Current recorded value','آخر قيمة مسجلة')}</dt><dd dir="ltr">${number(model.current?.values?.[model.metric])} ${esc(METRICS[model.metric].unit)}</dd></div><div><dt>${t('Personal median','الوسيط الشخصي')}</dt><dd dir="ltr">${number(base.median)} ${esc(METRICS[model.metric].unit)}</dd></div><div><dt>${['mood','energy'].includes(model.metric)?t('Observed category interval','مجال الفئات المرصود'):t('Observed personal P10–P90','المجال الشخصي المرصود P10–P90')}</dt><dd dir="ltr">${base.range?number(base.range.low)+'–'+number(base.range.high):'—'}</dd></div><div><dt>${t('Median absolute deviation · MAD','الانحراف المطلق الوسيط · MAD')}</dt><dd>${number(base.mad)}</dd></div><div><dt>${t('Absolute / percentage deviation','الانحراف المطلق / النسبي')}</dt><dd>${model.comparison?.available?number(model.comparison.absoluteDeviation)+' / '+(Number.isFinite(model.comparison.percentDeviation)?number(model.comparison.percentDeviation)+'%':t('Not applicable','لا ينطبق')):'—'}</dd></div><div><dt>${t('Data sufficiency','كفاية البيانات')}</dt><dd>${base.count} ${t('observations','قياسات')} · ${base.days} ${t('UTC days','أيام UTC')}</dd></div><div><dt>${t('Measurement context','ظروف القياس')}</dt><dd>${t(...(contextNames[model.context]||contextNames.unknown))}</dd></div><div><dt>${t('Last actual measurement time','آخر وقت قياس فعلي')}</dt><dd>${model.current?esc(stamp(model.current.timestamp)):'—'}</dd></div></dl><p class="dual-qualification">${t('The P10–P90 interval is descriptive history, not a safe range. A baseline needs at least five valid observations on three UTC dates with compatible acquisition context.','المجال P10–P90 وصف للتاريخ، وليس نطاق أمان. خط الأساس يحتاج خمسة قياسات صالحة على الأقل في ثلاثة تواريخ UTC، مع توافق طريقة وظروف القياس.')}</p>${base.reason&&base.status!=='established'?`<p class="dual-muted">${t('Unavailable reason','سبب عدم الإتاحة')}: ${esc(baselineReason(base.reason))}</p>`:''}${baselineSelection(base)}${historicalReference(model)}${base.provisional?`<p class="dual-qualification">${t('Descriptive/provisional baseline. Repeated unusual values cannot establish medical safety. General safety rules remain active.','خط أساس وصفي أو مؤقت. تكرار القيم غير المعتادة لا يثبت الأمان الطبي. تظل قواعد السلامة العامة فعالة.')}</p>`:''}${threeLayers(model)}${model.current?`<div class="dual-actions"><button class="btn btn-primary" data-action="dual-followup" data-record="${esc(model.current.id)}" data-mode="${model.simulated?'demo':'real'}">${t('Review follow-up questions','راجع أسئلة المتابعة')}</button>${model.simulated?'':`<button class="btn btn-light" data-action="dual-case" data-record="${esc(model.current.id)}" data-mode="real">${t('Prepare a case','جهّز ملف متابعة')}</button>`}</div>`:''}</section>`}
 function libraryView(){return `<section class="panel panel-pad dual-library"><div class="section-heading"><div><span class="eyebrow">${esc(referenceLibrary.label)}</span><h2>${t('Versioned research reference library','مكتبة المراجع البحثية بإصداراتها')}</h2></div><button class="btn btn-light" data-action="dual-library-export">${t('Download source library','تنزيل مكتبة المصادر')}</button></div><p>${t('Version','الإصدار')}: <code>${esc(referenceLibrary.referenceVersion)}</code> · ${t('31 published group summaries across four indicators. No participant-level distribution is available.','٣١ ملخصًا منشورًا لمجموعات عبر أربعة مؤشرات. لا يتوفر توزيع لقياسات الأفراد.')}</p>${referenceLibrary.entries.map(entry=>`<details><summary>${esc(label(entry.indicator))} · ${entry.sampleSize} ${t('participants in study cohort','مشاركًا في عينة الدراسة')}</summary><p>${esc(entry.studyTitle)}</p><p>${esc(entry.datasetIdentifier)} · ${esc(entry.measurementUnits)}</p><p>${esc(words(entry.population.description))}</p><p>${t('Acquisition','طريقة الجمع')}: ${esc(entry.acquisitionMethod.description)}</p><p>${t('Processing','المعالجة')}: ${esc(entry.processingMethod)}</p><ul>${entry.summaries.map(row=>`<li><span dir="ltr">${esc(row.timepoint)}${row.posture?' · '+esc(row.posture):''}: ${row.mean} ± ${row.standardDeviation} ${esc(entry.measurementUnits)}</span> · ${t('group mean ± SD','متوسط المجموعة ± الانحراف المعياري')}</li>`).join('')}</ul><ul>${entry.limitations.map(limit=>`<li>${esc(limit)}</li>`).join('')}</ul><a class="text-link" href="${esc(entry.publication.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('Original publication','المنشور الأصلي')}${icon('external')}</a></details>`).join('')}<p>${t('Other requested indicators retain an insufficient-published-data state. Research statistics are separate from personal measurements and medical safety rules.','المؤشرات الأخرى تحتفظ بحالة بيانات منشورة غير كافية. إحصاءات البحث منفصلة عن القياسات الشخصية وقواعد السلامة الطبية.')}</p></section>`}
 function controls(){const opts=options();return `<form id="dual-controls" class="dual-controls"><label>${t('Indicator','المؤشر')}<select name="metric">${Object.keys(METRICS).map(metric=>`<option value="${metric}" ${selectedMetric===metric?'selected':''}>${esc(label(metric))}</option>`).join('')}</select></label><label>${t('Baseline period','فترة خط الأساس')}<select name="baselineType">${Object.entries(typeNames).map(([key,names])=>`<option value="${key}" ${opts.baselineType===key?'selected':''}>${t(...names)}</option>`).join('')}</select></label><label>${t('Activity context','ظروف النشاط')}<select name="context">${Object.entries(contextNames).map(([key,names])=>`<option value="${key}" ${selectedContext===key?'selected':''}>${t(...names)}</option>`).join('')}</select></label><label>${t('Rolling window · days','النافذة المتحركة · أيام')}<input type="number" min="7" max="14" name="rollingDays" value="${opts.rollingDays}" required></label><label>${t('Trend period','فترة الاتجاه')}<select name="period">${Object.entries(periodNames).map(([key,names])=>`<option value="${key}" ${selectedPeriod===key?'selected':''}>${t(...names)}</option>`).join('')}</select></label><label class="dual-context-consent"><span><input type="checkbox" name="researchConfirmed" ${researchConfirmed?'checked':''}> ${t('I reviewed the selected research protocol, mission phase, posture and acquisition method before comparison.','راجعت بروتوكول البحث المختار ومرحلة الرحلة والوضعية وطريقة القياس قبل المقارنة.')}</span></label><button class="btn btn-light" type="submit">${t('Update analysis','تحديث التحليل')}</button></form>`}
 function trendCard(trend,forDemo){const key=forDemo?'demo':'real',acknowledged=dual.acknowledgements[key][trend.id],current=trend.current;return `<article class="dual-trend ${isReview(trend)?'dual-review':''}"><div class="section-heading"><h3>${esc(label(trend.metric))} · ${esc(t(...(categoryNames[trend.category||trend.classification]||categoryNames.insufficient)))}</h3><span class="pill">${esc(t(...(contextNames[trend.context]||contextNames.unknown)))}</span></div><p>${esc(words(trend.explanation))}</p><p>${t('Current','الحالي')}: <span dir="ltr">${number(current?.value)} ${esc(trend.unit||METRICS[trend.metric]?.unit||'')}</span> · ${current?.timestamp?esc(stamp(current.timestamp)):'—'}</p><p>${t('Observation period','فترة الملاحظة')}: ${esc(trend.period||selectedPeriod)} · ${esc(stamp(trend.windowStart))} → ${esc(stamp(trend.windowEnd))}</p><p>${t('Personal median','الوسيط الشخصي')}: ${number(trend.baseline?.median)} · ${esc(safetyText(trend.safety))}</p><p>${esc(researchText(trend.research))}</p><p>${esc(words(trend.followUp))}</p>${trend.concurrentChanges?`<p class="dual-qualification">${esc(words(trend.concurrentChanges.interpretation))}</p>`:''}<details><summary>${t('Supporting recorded measurements','القياسات المسجلة الداعمة')}</summary><ul>${(trend.supportingMeasurements||[]).map(point=>`<li>${esc(stamp(point.timestamp))} · <span dir="ltr">${number(point.value)} ${esc(trend.unit||'')}</span> · ${esc(point.context)} · ${esc(point.source_tag||point.source||'unknown')} · <code>${esc(point.id)}</code></li>`).join('')||`<li>${t('Insufficient supporting observations.','القياسات الداعمة غير كافية.')}</li>`}</ul></details>${isReview(trend)?`<div class="dual-actions">${acknowledged?`<span class="dual-muted">${t('Acknowledged; remains unresolved.','تم الاطلاع؛ يظل غير محلول.')} ${esc(stamp(acknowledged))}</span>`:`<button class="btn btn-light" data-action="dual-ack" data-id="${esc(trend.id)}" data-mode="${key}">${t('Acknowledge · keep unresolved','تم الاطلاع · يظل غير محلول')}</button>`}${current?.id?`<button class="btn btn-light" data-action="dual-followup" data-record="${esc(current.id)}" data-mode="${key}">${t('Open follow-up','افتح المتابعة')}</button>`:''}</div>`:''}</article>`}
 function trendsSection(forDemo=mode()==='demo'){const trends=allTrends(forDemo);return `<section class="panel panel-pad"><h2>${t('Explainable longitudinal trends','اتجاهات زمنية قابلة للفهم')}</h2><p class="dual-qualification">${t('Deterministic prototype rules summarize repeated observations. Category labels are not diagnoses or validated medical alert severities. Repeated samples within one day do not create multiple days of evidence.','قواعد محددة في النموذج تلخص الملاحظات المتكررة. التصنيفات ليست تشخيصًا أو درجات خطورة طبية معتمدة. تكرار العينات في يوم واحد لا ينشئ أيامًا متعددة من الأدلة.')}</p><div class="dual-trend-list">${trends.length?trends.map(trend=>trendCard(trend,forDemo)).join(''):`<p>${t('Insufficient Data — record actual measurements with their times and context.','بيانات غير كافية؛ سجل قياسات فعلية مع وقتها وسياقها.')}</p>`}</div></section>`}
 function demoEntry(){if(mode()!=='demo')return '';return `<section class="panel panel-pad dual-demo-entry"><h2>${t('Add a simulated crew observation','أضف قياسًا لطاقم المحاكاة')}</h2><p>${t('This form only updates the separate simulated ledger. No simulated value enters your personal health history.','النموذج يعدل سجل المحاكاة المنفصل فقط. لا يدخل أي رقم محاكى إلى سجلك الصحي الشخصي.')}</p><form id="dual-demo-entry"><div class="dual-controls"><label>${t('Scenario timestamp · ISO UTC','وقت السيناريو · ISO UTC')}<input name="timestamp" type="text" value="${new Date().toISOString()}" required></label><label>${t('Context','الظروف')}<select name="context">${Object.entries(contextNames).filter(([key])=>!['unknown','other'].includes(key)).map(([key,names])=>`<option value="${key}">${t(...names)}</option>`).join('')}</select></label><label>${t('Simulated source','مصدر محاكى')}<select name="simulated_source"><option value="manual">${t('Manual Entry','إدخال يدوي')}</option><option value="device">${t('Device Measurement · simulated','قياس جهاز · محاكاة')}</option><option value="crew">${t('Crew Observation','ملاحظة الطاقم')}</option></select></label></div><div class="dual-demo-values">${Object.entries(METRICS).filter(([key])=>key!=='eda').map(([key,metric])=>`<label>${esc(label(key))} (${esc(metric.unit)})<input name="${key}" type="number" min="${metric.min}" max="${metric.max}" step="${metric.step}"></label>`).join('')}</div><button class="btn btn-primary" type="submit">${t('Save simulated observation','احفظ قياس المحاكاة')}</button></form></section>`}
 function demoFollowUp(){if(mode()!=='demo'||!followUpId)return '';const record=demo.records.find(item=>item.id===followUpId);if(!record)return '';return `<section class="panel panel-pad dual-demo-entry" id="dual-demo-followup"><h2>${t('Simulated follow-up questionnaire','أسئلة متابعة المحاكاة')}</h2><p>${t('Educational demonstration only. Answers remain in the simulated case history; no clinician is contacted. A real emergency must follow approved mission procedures without waiting for this app.','عرض تعليمي فقط. الإجابات تبقى في سجل حالات المحاكاة؛ لا يتم التواصل مع طبيب. الطوارئ الحقيقية تتبع إجراءات المهمة المعتمدة دون انتظار التطبيق.')}</p><p>${esc(record.id)} · ${esc(stamp(record.timestamp))}</p><form id="dual-demo-followup-form"><input type="hidden" name="recordId" value="${esc(record.id)}">${[['warningSigns','Any serious or sudden warning signs?','هل توجد علامات شديدة أو مفاجئة؟'],['rechecked','Was another measurement actually taken?','هل أُخذ قياس آخر بالفعل؟'],['persistent','Is the concern continuing or recurring?','هل المشكلة مستمرة أو متكررة؟']].map(([key,en,ar])=>`<label class="dual-question">${t(en,ar)}<select name="${key}"><option value="unknown">${t('Unknown','غير معروف')}</option><option value="yes">${t('Yes','نعم')}</option><option value="no">${t('No','لا')}</option></select></label>`).join('')}<label class="dual-question">${t('Notes / questions for medical review','ملاحظات أو أسئلة للمراجعة الطبية')}<textarea name="notes" maxlength="2000"></textarea></label><p class="dual-qualification">${t('If warning signs are present, the demonstrated next step is immediate escalation to qualified medical personnel under the mission emergency procedure. A repeat measurement or “no” answer never proves safety.','عند وجود علامات خطر، الخطوة المعروضة هي التصعيد الفوري للمختص الطبي وفق إجراء طوارئ المهمة. إعادة القياس أو إجابة «لا» لا تثبت السلامة.')}</p><button class="btn btn-primary" type="submit">${t('Save simulated case answers','احفظ إجابات حالة المحاكاة')}</button></form></section>`}
 function audit(){const snapshots=dual.history[mode()];return `<details class="panel panel-pad dual-audit"><summary>${t('Historical baseline snapshots','لقطات خط الأساس التاريخية')} · ${snapshots.length}</summary><p>${t('Up to 500 distinct analysis snapshots are retained for each workspace. Raw observations are never deleted by this retention limit. A snapshot is descriptive, not medical approval.','تُحفظ حتى ٥٠٠ لقطة تحليل مميزة لكل مساحة. هذا الحد لا يحذف القياسات الأصلية. اللقطة وصفية وليست اعتمادًا طبيًا.')}</p>${[...snapshots].reverse().slice(0,30).map(item=>`<p>${esc(label(item.metric))} · ${t(...typeNames[item.type])} · ${number(item.median)} · ${item.count} ${t('records','قياسات')} · ${esc(stamp(item.asOf))}</p>`).join('')}</details>`}
 function judgeTour(){
  const summary=getJudgeDemoSummary();if(!summary)return '';
  const choices=[['heart','Heart rate','ضربات القلب'],['sys','Blood pressure','ضغط الدم'],['sleep','Sleep duration','مدة النوم'],['mood','Mood','المزاج']];
  return `<section class="panel panel-pad dual-judge-tour" aria-label="${t('Simulated seven-day reviewer tour','جولة مراجعة أسبوع محاكى')}"><div class="section-heading"><div><span class="eyebrow">${t('SIMULATED · FOR REVIEWERS','محاكاة · للمراجعين')}</span><h2>${t('Try a week of crew health observations.','جرّب أسبوعًا من قياسات صحة الطاقم.')}</h2></div><span class="pill blue">${t('7-day preview','معاينة ٧ أيام')}</span></div><p>${summary.recordCount} ${t('simulated observations across','تسجيلات محاكاة عبر')} ${summary.observedDays} ${t('recorded calendar days in this seven-day window. Missing days remain empty.','أيام تقويمية مسجلة في نافذة الأيام السبعة. الأيام الناقصة تظل فارغة.')}</p><p class="dual-judge-window">${t('Scenario snapshot','لقطة السيناريو')}: <time datetime="${esc(summary.asOf)}">${esc(stamp(summary.asOf))}</time> · ${t('Seven calendar days ending at this recorded scenario time.','سبعة أيام تقويمية تنتهي عند وقت السيناريو المسجل.')}<br><time datetime="${esc(summary.start)}">${esc(stamp(summary.start))}</time> → <time datetime="${esc(summary.end)}">${esc(stamp(summary.end))}</time> · ${esc(summary.timeZone)}</p><div class="dual-judge-metrics">${choices.map(([metric,en,ar])=>`<button type="button" class="btn ${selectedMetric===metric?'btn-primary':'btn-light'}" data-action="dual-judge-metric" data-metric="${metric}" aria-pressed="${selectedMetric===metric}"><span>${t(en,ar)}</span><small>${summary.metricCounts[metric]} ${t('readings','قراءات')}</small></button>`).join('')}</div><ol><li>${t('Choose an indicator and inspect actual scenario timestamps, points and connected lines below.','اختار مؤشرًا وراجع أوقات السيناريو والنقاط والخطوط المتصلة بالأسفل.')}</li><li>${t('Compare the personal historical baseline with the separately labeled published research summary. No research statistic becomes a safety range.','قارن الخط المرجعي الشخصي بملخص البحث المنشور الموسوم بشكل منفصل. إحصاءات البحث لا تصبح نطاق أمان.')}</li><li>${t('Add a simulated reading, review the follow-up and download the analysis report. Nothing is sent to a clinician.','أضف قراءة محاكاة، وراجع المتابعة ونزّل تقرير التحليل. لا يُرسل شيء لطبيب.')}</li></ol><p class="dual-muted">${t('The earlier simulated history is retained for baseline calibration. Personal observations are never replaced by this preview.','التاريخ المحاكى الأقدم محفوظ لبناء الخط المرجعي. هذه المعاينة لا تستبدل التسجيلات الشخصية أبدًا.')}</p></section>`;
 }
 function banner(){return mode()==='demo'?`<div class="dual-simulation" role="status"><strong>${t('SIMULATED CREW WORKSPACE','مساحة طاقم محاكى')}</strong><p>${t('Fictional mission and synthetic measurements. NASA research references remain authentic and separate. No personal record is changed.','مهمة خيالية وقياسات مولدة للمحاكاة. مراجع ناسا البحثية تظل حقيقية ومنفصلة. لا يُعدل أي تسجيل شخصي.')}</p><button class="btn btn-light" data-action="dual-real">${t('Return to personal records','ارجع للسجل الشخصي')}</button></div>`:''}
 function view(){const model=metricModel(selectedMetric);return `<div class="page-heading"><div><span class="eyebrow">COSMOVITAL · DUAL BASELINE</span><h1>${t('Space evidence. Your own history. Three independent checks.','دليل الفضاء وتاريخك الشخصي، بثلاث مراجعات مستقلة.')}</h1><p>${t('Personal medians, compatible published research and explainable longitudinal observations.','الوسيط الشخصي والبحث المنشور المتوافق والملاحظات الزمنية القابلة للتفسير.')}</p></div><div class="heading-buttons dual-heading-actions"><button class="btn btn-primary" data-action="dual-judge-demo">${t('Try 7-Day Demo','جرّب ديمو أسبوع')}</button><button class="btn btn-light" data-action="dual-export">${icon('download')}${t('Export analysis report','تصدير تقرير التحليل')}</button><button class="btn btn-light" data-action="dual-load-demo">${t(demo?'Reload Demo Crew Data':'Load Demo Crew Data',demo?'إعادة تحميل بيانات الطاقم المحاكى':'تحميل بيانات طاقم محاكى')}</button>${demo&&!demo.active?`<button class="btn btn-light" data-action="dual-demo">${t('Open saved Demo Crew','افتح الطاقم المحاكى المحفوظ')}</button>`:''}${demo?`<button class="btn btn-light" data-action="dual-reset-demo">${t('Reset Demo Data','مسح بيانات المحاكاة')}</button>`:''}</div></div>${banner()}${judgeTour()}${error?`<div class="warning-banner" role="alert">${esc(error)}</div>`:''}${feedback?`<div class="notice" role="status">${esc(feedback)}</div>`:''}<div class="notice"><p>${t('Research summaries are not NASA-approved safety limits. No available research distribution is invented from mean ± SD. General medical warnings remain independent, and missing comparisons do not establish safety.','ملخصات البحث ليست حدود أمان معتمدة من ناسا. لا يُختلق توزيع مرجعي من المتوسط ± الانحراف المعياري. التحذيرات الطبية مستقلة، ونقص المقارنات لا يثبت السلامة.')}</p></div>${controls()}<div class="dual-layout">${baselineCard(model)}${chartView(model)}${demoFollowUp()}${trendsSection()}${demoEntry()}${audit()}${libraryView()}</div>`}
 function overview(){const input=modeRecords(false),count=input.length;return `<section class="panel panel-pad dual-overview"><div class="section-heading"><div><span class="eyebrow">DUAL BASELINE</span><h2>${t('Compare with evidence and with yourself.','قارن بالدليل وبتاريخك الشخصي.')}</h2></div><a class="btn btn-primary" href="#dual-baseline">${t('Open Dual-Baseline workspace','افتح مساحة خط الأساس المزدوج')}</a></div><p>${t('General medical prompts, compatible spaceflight research and personal history are evaluated separately. A missing research reference never blocks personal recording.','تُراجع المراجع الطبية العامة وأبحاث الفضاء المتوافقة والتاريخ الشخصي بشكل مستقل. غياب المرجع البحثي لا يمنع تسجيل القياسات.')}</p><div class="dual-overview-grid">${['heart','oxygen','sleep'].map(metric=>{const model=metricModel(metric,false);return `<article><strong>${esc(label(metric))}</strong><span>${number(model.current?.values?.[metric])} ${esc(METRICS[metric].unit)}</span><small>${model.baseline.status==='established'?t('Personal median ','الوسيط الشخصي ')+number(model.baseline.median):t('Insufficient Personal Data','بيانات شخصية غير كافية')}</small></article>`}).join('')}</div><p class="dual-muted">${count} ${t('actual personal observations remain separate from the optional simulated crew.','تسجيلات شخصية فعلية تظل منفصلة عن الطاقم المحاكى الاختياري.')}</p></section>`}
 function alerts(){const trends=allTrends(false).filter(isReview);return `<section class="panel panel-pad dual-alert-summary"><div class="section-heading"><h2>${t('Longitudinal trend reviews','مراجعات الاتجاهات الزمنية')}</h2><a class="text-link" href="#dual-baseline">${t('Inspect baselines and evidence','راجع خط الأساس والأدلة')}</a></div><p>${t('Trend reviews are descriptive software rules, separate from medical reference prompts below. Acknowledging a trend keeps it unresolved.','مراجعات الاتجاه قواعد برمجية وصفية منفصلة عن التنبيهات الطبية المرجعية التالية. الاطلاع لا يحل المشكلة.')}</p>${trends.length?trends.map(trend=>trendCard(trend,false)).join(''):`<p>${t('No current trend-review rule matched. Missing data and symptoms still require attention.','لا توجد مطابقة حالية لقاعدة مراجعة اتجاه. نقص البيانات والأعراض يظلان بحاجة للانتباه.')}</p>`}</section>`}
 function chartSummary(metric){if(!METRICS[metric])return '';const model=metricModel(metric,false);return `<div class="dual-chart-summary"><strong>${t('Personal baseline comparison','مقارنة خط الأساس الشخصي')}</strong><span>${model.baseline.status==='established'?t('Median ','الوسيط ')+number(model.baseline.median)+' '+METRICS[metric].unit:t('Insufficient Personal Data','بيانات شخصية غير كافية')}</span><small>${esc(researchText(model.research))} · ${t('Personal records only; chart values are not simulated.','السجل الشخصي فقط؛ قيم الرسم ليست محاكاة.')}</small></div>`}
 function exportLocalState(){return {schemaVersion:1,demo:demo?clone(demo):null,dual:clone(dual)}}
 function validateLocalState(raw){if(!plain(raw)||raw.schemaVersion!==1)throw new Error('Invalid local analysis extension.');return {schemaVersion:1,demo:raw.demo===null?null:validateDemoCrew(raw.demo),dual:validateDualState(raw.dual)}}
 function restoreLocalState(raw){const checked=validateLocalState(raw),local=storage();if(!local)throw new Error('Local storage unavailable.');const keys=[DEMO_STORAGE_KEY,DUAL_STORAGE_KEY],before=keys.map(key=>local.getItem(key));try{if(checked.demo)local.setItem(DEMO_STORAGE_KEY,JSON.stringify(checked.demo));else local.removeItem(DEMO_STORAGE_KEY);local.setItem(DUAL_STORAGE_KEY,JSON.stringify(checked.dual))}catch(issue){try{keys.forEach((key,i)=>before[i]===null?local.removeItem(key):local.setItem(key,before[i]))}catch{throw new Error('Analysis restore failed and rollback was not completed; recover your backup.')}throw issue}demo=checked.demo;dual=checked.dual;error='';recoveryRequired=false;return exportLocalState()}
 function clearPersonalState(){const next=clone(dual);next.acknowledgements.real={};next.history.real=[];writeDual(next)}
 function report(){const forDemo=mode()==='demo',input=records();return {app:'CosmoVital',type:'dual-baseline-analysis-report',schemaVersion:1,exportedAt:new Date().toISOString(),analysisAsOf:new Date(analysisTime(forDemo)).toISOString(),simulated:forDemo,mission:{start:missionStart(forDemo),name:forDemo?demo.mission.name:getSettings().missionName||'',fictional:forDemo||getSettings().missionSimulation===true},options:options(),researchLibrary:referenceLibrary,measurements:clone(input),selectedEvaluation:metricModel(selectedMetric),trends:allTrends(),baselineSnapshots:clone(dual.history[mode()]),acknowledgements:clone(dual.acknowledgements[mode()]),simulatedFollowUps:forDemo?clone(demo.followUps):[],clinicalAssessment:false,deliveryStatus:'not-sent',limitations:['Descriptive research and personal history never establish medical safety.','No clinician was contacted.','Local storage and JSON exports are not encrypted medical-grade storage.']}}
 async function action(target){const action=target?.dataset?.action;if(!action?.startsWith('dual-'))return false;error='';feedback='';try{
  if(action==='dual-judge-demo')startJudgeDemo();
  else if(action==='dual-judge-metric'){if(!isDemoActive())throw new Error(t('Start the simulated seven-day preview first.','ابدأ معاينة الأسبوع المحاكى أولًا.'));const metric=target.dataset.metric;if(!['heart','sys','sleep','mood'].includes(metric))throw new Error(t('Choose a supported demo indicator.','اختار مؤشر محاكاة مدعومًا.'));selectedMetric=metric;selectedContext=metric==='sleep'?'sleep':'resting';researchConfirmed=false}
  else if(action==='dual-chart-range'){if(!['24','7','30'].includes(target.dataset.range))throw new Error(t('Choose 24 hours, 7 days or 30 days.','اختار ٢٤ ساعة أو ٧ أيام أو ٣٠ يومًا.'));selectedChartRange=target.dataset.range}
  else if(action==='dual-load-demo'){if(demo&&!(await (ctx.confirm||globalThis.confirm)?.(t('Replace only the existing simulated crew data? Personal records will remain unchanged.','استبدال بيانات الطاقم المحاكى فقط؟ السجل الشخصي لن يتغير.'))))return true;persistDemo(createDemoCrew());followUpId='';researchConfirmed=false;selectedChartRange='7';demoType='early-mission';feedback=t('Simulated crew loaded in a separate workspace.','تم تحميل الطاقم المحاكى في مساحة منفصلة.')}
  else if(action==='dual-reset-demo'){if(!demo)return true;if(!(await (ctx.confirm||globalThis.confirm)?.(t('Delete only simulated crew data and its simulated analysis history?','حذف بيانات المحاكاة وتاريخ تحليلها المحاكى فقط؟'))))return true;clearDemoCrew(storage());demo=null;followUpId='';const next=clone(dual);next.history.demo=[];next.acknowledgements.demo={};writeDual(next)}
  else if(action==='dual-real'){if(demo)persistDemo({...demo,active:false});followUpId='';researchConfirmed=false;selectedChartRange='7'}
  else if(action==='dual-demo'){if(demo)persistDemo({...demo,active:true});researchConfirmed=false;selectedChartRange='7'}
  else if(action==='dual-library-export')download(JSON.stringify(referenceLibrary,null,2),'CosmoVital-research-library.json','application/json');
  else if(action==='dual-export')download(JSON.stringify(report(),null,2),'CosmoVital-dual-baseline-report.json','application/json');
  else if(action==='dual-ack'){const key=target.dataset.mode==='demo'?'demo':'real',trend=allTrends(key==='demo').find(item=>item.id===target.dataset.id&&isReview(item));if(!trend)throw new Error(t('This trend is no longer in the current analysis.','الاتجاه لم يعد موجودًا في التحليل الحالي.'));const next=clone(dual);next.acknowledgements[key][trend.id]=next.acknowledgements[key][trend.id]||new Date().toISOString();writeDual(next)}
  else if(action==='dual-followup'||action==='dual-case'){const forDemo=target.dataset.mode?target.dataset.mode==='demo':mode()==='demo',record=modeRecords(forDemo).find(item=>item.id===target.dataset.record);if(!record)throw new Error(t('The selected observation no longer exists.','التسجيل المختار لم يعد موجودًا.'));if(forDemo){if(!demo?.active)persistDemo({...demo,active:true});followUpId=record.id}else if(action==='dual-followup')ctx.openFollowUp?.(record);else ctx.openCase?.(record)}
  else return false;
 }catch(issue){error=issue.message}render();return true}
 async function submit(form,fd){if(!['dual-controls','dual-demo-entry','dual-demo-followup-form'].includes(form.id))return false;error='';feedback='';try{
  if(form.id==='dual-controls'){const metric=String(fd.get('metric')),context=String(fd.get('context')),type=String(fd.get('baselineType')),period=String(fd.get('period')),rollingDays=Number(fd.get('rollingDays'));if(!METRICS[metric]||!contextNames[context]||!typeNames[type]||!periodNames[period]||!Number.isInteger(rollingDays)||rollingDays<7||rollingDays>14)throw new Error(t('Choose valid analysis settings.','اختار إعدادات تحليل صالحة.'));selectedMetric=metric;selectedContext=context;selectedPeriod=period;researchConfirmed=fd.get('researchConfirmed')==='on';if(mode()==='demo'){demoType=type;demoRolling=rollingDays}else if(ctx.saveSettings)await ctx.saveSettings({baselineType:type,baselineContext:context,rollingDays})}
  else if(form.id==='dual-demo-entry'){if(mode()!=='demo')throw new Error('Load simulated crew data first.');const values={};for(const metric of Object.keys(METRICS)){const value=fd.get(metric);if(value!==null&&String(value).trim()!=='')values[metric]=String(value)}persistDemo(addDemoObservation(demo,{timestamp:String(fd.get('timestamp')),context:String(fd.get('context')),simulated_source:String(fd.get('simulated_source')),values}));feedback=t('Saved only to simulated crew data.','تم الحفظ في بيانات المحاكاة فقط.')}
  else{if(mode()!=='demo')throw new Error('Open the simulated workspace first.');const recordId=String(fd.get('recordId'));if(recordId!==followUpId||!demo.records.some(record=>record.id===recordId))throw new Error('Simulated follow-up observation changed.');const answers=Object.fromEntries(['warningSigns','rechecked','persistent','notes'].map(key=>[key,String(fd.get(key)|| (key==='notes'?'':'unknown'))]));const next=clone(demo);next.followUps.push({recordId,answeredAt:new Date().toISOString(),simulated:true,answers});persistDemo(next);feedback=answers.warningSigns==='yes'?t('Simulated warning signs recorded. Demonstrated response: immediate mission medical escalation; no transmission was made.','سُجلت علامات خطر في المحاكاة. الاستجابة المعروضة: تصعيد طبي فوري وفق المهمة؛ لم يُرسل شيء.'):t('Simulated case answers saved. This does not establish recovery or medical clearance.','حُفظت إجابات حالة المحاكاة. هذا لا يثبت التعافي أو السلامة الطبية.');followUpId=''}
 }catch(issue){error=issue.message}render();return true}
 function recordSaved(record){const evaluation=evaluateMeasurement(record,modeRecords(false),options(false));for(const item of Object.values(evaluation.metrics||{}))retainBaseline(item.layers?.personal?.baseline,record.timestamp,false);return evaluation}
 return {view,overview,alerts,chartSummary,startJudgeDemo,isDemoActive,getDemoRecords,demoMission,getJudgeDemoSummary,getChartModel:()=>clone(buildHistoryModel(metricModel(selectedMetric))),action,submit,change:()=>false,recordSaved,exportLocalState,validateLocalState,restoreLocalState,reload,clearPersonalState};
}
